unlabeled=collections.Counter(); unlab_trials=0; tot_trials=0
for k,v in keys.items():
    merged={}
    for m in v['maps']:
        for w,s in m.items():
            if not np.isnan(s): merged[w]=int(s)
    for w,c in v['wallcount'].items():
        tot_trials+=c
        if w not in merged:
            unlabeled[(k,w)]=c; unlab_trials+=c
    v['merged']=merged
print('total trials',tot_trials,'unlabeled trials',unlab_trials)
for (k,w),c in unlabeled.items(): print('UNLABELED',k,w,c)
